{
  "role": "Adversarial Reviewer",
  "assumptions": [
    "The review target is an argument claiming global smoothness of unforced incompressible 3D Navier-Stokes on R^3 with smooth, rapidly decaying, divergence-free initial data.",
    "This output concerns review structure only; it does not assert that the Navier-Stokes problem is solved.",
    "All mathematical claims below are unverified unless directly established in this response."
  ],
  "obligations": [
    "Identify plausible overclaim patterns without pretending to prove or disprove global smoothness.",
    "Convert each overclaim pattern into a checkable question that can be applied to the proposed argument.",
    "State limitations of this review-role output."
  ],
  "failure_modes": [
    {
      "overclaim": "Norm control is treated as sufficient. A bound in one norm (for example, energy, L^p, or a critical norm) is used as if it directly gives smoothness or precludes finite-time blow-up, without controlling the quantities actually needed for regularity.",
      "checkable_question": "Which norm is bounded, on what time interval, with what constants, and does that bound directly imply the regularity criteria actually invoked in the argument?"
    },
    {
      "overclaim": "Quantifier ambiguity or illegal exchange of limits. A uniform-in-time statement, a local-in-time statement, or an epsilon-dependent bound is silently promoted to a global or uniform statement, often through swapping a limit in a parameter with a time limit.",
      "checkable_question": "For every bound used, are the quantifiers in time, initial data, frequency, and approximation parameter stated explicitly, and is any interchange of limits justified by a uniform estimate?"
    },
    {
      "overclaim": "Regularity continuation is assumed without a verified continuation criterion. The argument obtains smoothness on [0,T) and then asserts it extends to T or to infinity without proving the required blow-up criterion or controlling the limiting solution.",
      "checkable_question": "What exact continuation criterion is proved or assumed, and does the argument verify its hypotheses at the terminal time, including whether the limiting object is still a solution of the original equation?"
    },
    {
      "overclaim": "Approximation or localization is used without uniform control. A solution is approximated by smoother or truncated data, and properties of the approximations are transferred to the limit without uniform estimates preventing loss of regularity or mass/energy in the limit.",
      "checkable_question": "Are the approximation and localization procedures uniform in the approximation parameter, and does the argument prove that the limit retains the regularity, divergence-free condition, and equation satisfied in the appropriate sense?"
    },
    {
      "overclaim": "Auxiliary assumptions are hidden in the proof. The argument uses an unproved bootstrapping hypothesis, smallness condition, spectral gap, or structural cancellation and later reports the result as unconditional.",
      "checkable_question": "List every hypothesis used, including smallness and cancellation assumptions; is each one either proved from the given initial data or explicitly stated as an assumption, and would the conclusion still be global without it?"
    }
  ],
  "limitations": [
    "This is an exploratory proof-review checklist, not a proof or disproof of global regularity.",
    "The listed overclaim patterns are generic; their applicability to any specific proposed argument requires inspection of that argument.",
    "No citation, theorem, or external evidence is asserted here.",
    "The output does not claim to resolve Navier-Stokes or establish any new mathematical result."
  ]
}
